--
-- Table structure for table `production_tooling`
--

DROP TABLE IF EXISTS `production_tooling`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_tooling` (
  `tooling_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tooling_no` varchar(50) NOT NULL COMMENT '工装编号（网框编号/刀模编号，唯一）',
  `tooling_name` varchar(200) NOT NULL COMMENT '名称（如：3#丝印网框、主面板模切刀模）',
  `tooling_type` varchar(20) NOT NULL COMMENT '类型：SCREEN=网框 DIE=刀模（静态枚举）',
  `spec` varchar(512) DEFAULT NULL COMMENT '参数（如：材质：xxx\n尺寸：xxx，长度512）',
  `mesh_count` int DEFAULT NULL COMMENT '目数（如 200、300）',
  `frame_size` varchar(100) DEFAULT NULL COMMENT '框尺寸（如 400×500mm）',
  `mesh_material` varchar(50) DEFAULT NULL COMMENT '网布材质（聚酯/尼龙/不锈钢）',
  `tension` decimal(6,2) DEFAULT NULL COMMENT '张紧力(N/cm)',
  `blade_height` decimal(8,2) DEFAULT NULL COMMENT '刀高(mm)',
  `die_material` varchar(50) DEFAULT NULL COMMENT '刀模材质（钢刀/蚀刻/激光）',
  `die_size` varchar(100) DEFAULT NULL COMMENT '模切尺寸（如 120×80mm）',
  `life_limit` int DEFAULT NULL COMMENT '设计冲切寿命上限(次)',
  `current_count` int DEFAULT '0' COMMENT '已冲切次数（手工维护+报工累加）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0=在库 1=使用中 2=清洗/保养中 3=维修中 4=报废（静态枚举）',
  `location` varchar(200) DEFAULT NULL COMMENT '存放位置（货架/柜号）',
  `department` varchar(100) DEFAULT NULL COMMENT '使用部门',
  `responsible` varchar(64) DEFAULT NULL COMMENT '责任人',
  `customer` varchar(100) DEFAULT NULL COMMENT '客户（定制工装所属客户）',
  `enable_date` date DEFAULT NULL COMMENT '启用日期',
  `last_use_time` datetime DEFAULT NULL COMMENT '最后使用时间',
  `use_count` int DEFAULT '0' COMMENT '累计使用次数',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志 0正常 1删除',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`tooling_id`),
  UNIQUE KEY `uk_tooling_no` (`tooling_no`),
  KEY `idx_type_status` (`tooling_type`,`status`),
  KEY `idx_name` (`tooling_name`)
) ENGINE=InnoDB AUTO_INCREMENT=7283 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='工装模具档案';
/*!40101 SET character_set_client = @saved_cs_client */;

