--
-- Table structure for table `quality_template_print_log`
--

DROP TABLE IF EXISTS `quality_template_print_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_template_print_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `template_id` bigint NOT NULL COMMENT '质量记录模板ID',
  `record_no` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '打印时记录编号快照',
  `biz_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型（如 sales_delivery）',
  `biz_id` bigint DEFAULT NULL COMMENT '业务单据ID',
  `operator_id` bigint DEFAULT NULL COMMENT '打印人用户ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打印人姓名快照',
  `print_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '打印时间',
  PRIMARY KEY (`id`),
  KEY `idx_template_id` (`template_id`),
  KEY `idx_print_time` (`print_time`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='质量记录模板打印留痕';
/*!40101 SET character_set_client = @saved_cs_client */;

