/*!50001 VIEW `v_user_permissions` AS select `u`.`user_id` AS `user_id`,`u`.`user_name` AS `user_name`,group_concat(distinct `m`.`perms` order by `m`.`perms` ASC separator ',') AS `permissions_list`,count(distinct `m`.`perms`) AS `permission_count` from (((`sys_user` `u` join `sys_user_role` `ur` on((`u`.`user_id` = `ur`.`user_id`))) join `sys_role_menu` `rm` on((`ur`.`role_id` = `rm`.`role_id`))) join `sys_menu` `m` on((`rm`.`menu_id` = `m`.`menu_id`))) where ((`m`.`perms` is not null) and (`m`.`perms` <> '')) group by `u`.`user_id`,`u`.`user_name` */;
